using Beep.OilandGas.Models.Data.Accounting;
using Beep.OilandGas.Models.Data.Company;
using Beep.OilandGas.Accounting.Models;
#if WORKFLOW_INBOX_FOCUSED
using System.Net;
using System.Text.Json;
using Beep.OilandGas.Models.Data;
using Beep.OilandGas.Web.Services;
using Moq;
using TheTechIdea.Beep.ConfigUtil;
using TheTechIdea.Beep.DataBase;
using TheTechIdea.Beep.Tools;
using Xunit;
namespace Beep.OilandGas.ApiService.Tests;
[Collection("CompanySalesJournalSource")]
public sealed class CompanySalesJournalPostingHttpTests
{
    [Fact] public async Task ActualApiClientUsesLiveOwnedSourceSeparatePostingGrantAndExactOriginalRecovery()
    {
        using var validation=CompanySalesInvoiceValidation.Enter();var f=new CompanySalesJournalSourceTests.Fixture();await f.Prepare();CompanySalesJournalPreparationHttpTests.Writes(f);var original=await f.Read();var preparation=new CompanySalesJournalPreparation(Guid.NewGuid().ToString("N"),Guid.NewGuid().ToString("N"),original,"explicit-api-posting-journal","Original financial source",original.Lines.Select(_=>Guid.NewGuid().ToString("N")).ToArray());var draft=await f.Journal.PrepareCompanySalesJournalAsync(preparation,f.Guard,f.Read);
        var types=f.Native.Rows.Select(value=>value.GetType()).Concat([typeof(SALES_JOURNAL_REVIEW_INTENT),typeof(SALES_JOURNAL_POSTING_INTENT),typeof(SALES_JOURNAL_POSTING_OUTCOME),typeof(GL_ENTRY)]).Distinct().ToDictionary(type=>type==typeof(GLAccountMapping)?"GL_ACCOUNT_MAPPING":type.Name,type=>type);f.Native.Source.Setup(value=>value.GetEntityStructure(It.IsAny<EntityStructure>(),true)).Returns((EntityStructure request,bool refresh)=>new ClassCreator(f.Native.Editor.Object).ConvertToEntityStructure(types[request.EntityName]));
        f.Native.Source.Setup(value=>value.InsertEntity("SALES_JOURNAL_REVIEW_INTENT",It.IsAny<object>())).Returns((string table,object value)=>{f.Native.Writes++;f.Native.Rows.Add(CompanyInventorySourceReview.Copy((SALES_JOURNAL_REVIEW_INTENT)value));return new ErrorsInfo{Flag=Errors.Ok};});var review=CompanySalesJournalReviewSource.Create("independent-reviewer",draft,original);await f.Journal.RecordCompanySalesJournalReviewAsync(new(Guid.NewGuid().ToString("N"),review,"APPROVE","CONFIRMED","Exact original balanced journal","CONFIRMED","Original source/period/account evidence","Independent journal approval"),f.Guard,()=>Task.FromResult(CompanyInventorySourceReview.Copy(review)));
        f.Native.Source.Setup(value=>value.InsertEntity("SALES_JOURNAL_POSTING_INTENT",It.IsAny<object>())).Returns((string table,object value)=>{f.Native.Writes++;f.Native.Rows.Add(CompanyInventorySourceReview.Copy((SALES_JOURNAL_POSTING_INTENT)value));return new ErrorsInfo{Flag=Errors.Ok};});
        f.Native.Source.Setup(value=>value.InsertEntity("GL_ENTRY",It.IsAny<object>())).Returns((string table,object value)=>{f.Native.Writes++;f.Native.Rows.Add(CompanyInventorySourceReview.Copy((GL_ENTRY)value));return new ErrorsInfo{Flag=Errors.Ok};});
        f.Native.Source.Setup(value=>value.InsertEntity("SALES_JOURNAL_POSTING_OUTCOME",It.IsAny<object>())).Returns((string table,object value)=>{f.Native.Writes++;f.Native.Rows.Add(CompanyInventorySourceReview.Copy((SALES_JOURNAL_POSTING_OUTCOME)value));return new ErrorsInfo{Flag=Errors.Ok};});f.Native.Writes=0;f.Native.Transactions.Clear();
        await using var host=await CompanySalesJournalSourceHttpTests.Start(f);var grants=CompanySalesJournalSourceHttpTests.Grants.Concat(["Accounting.ReviewSalesJournalPosting","Accounting.PostSalesJournal"]).ToArray();host.Context.Permissions=grants;host.Context.Actor="authorized-poster";host.Client.DefaultRequestHeaders.Remove("X-Test-Actor");host.Client.DefaultRequestHeaders.Add("X-Test-Actor","authorized-poster");using var company=CompanyGLAccountHttpTests.Selected(actor:"authorized-poster",grants:grants);var client=CompanyGLAccountHttpTests.Client(host.Client,company);
        var source=await client.GetCompanySalesJournalPostingSourceAsync("statutory","KWD",preparation.JournalId);source.Require();Assert.Equal("authorized-poster",source.ActorUserId);Assert.Equal(JsonSerializer.Serialize(original),JsonSerializer.Serialize(source.Current));var command=new CompanySalesJournalPostingCommand(Guid.NewGuid().ToString("N"),source,source.Reviewed.Lines.Select(_=>Guid.NewGuid().ToString("N")).ToArray(),"Explicit atomic journal posting");
        foreach(var missing in new[]{"Accounting.PostSalesJournal","Accounting.ReviewSalesJournalPosting","Accounting.ReviewSalesJournalSource"}){host.Context.Permissions=grants.Where(value=>value!=missing).ToArray();var refused=await Assert.ThrowsAsync<OilGasApiException>(()=>client.PostCompanySalesJournalAsync(command));Assert.Equal(HttpStatusCode.Forbidden,refused.StatusCode);Assert.Equal(0,f.Native.Writes);}host.Context.Permissions=grants;
        f.Receivable.Data.Invoice.Data.Assets.Setup(value=>value.CheckAssetAccessAsync("authorized-poster",source.Current.FieldId,"FIELD","WRITE",null)).ReturnsAsync(new AccessCheckResponse{HasAccess=false});var denied=await Assert.ThrowsAsync<OilGasApiException>(()=>client.PostCompanySalesJournalAsync(command));Assert.Equal(HttpStatusCode.Forbidden,denied.StatusCode);Assert.Equal(0,f.Native.Writes);f.Receivable.Data.Invoice.Data.Assets.Setup(value=>value.CheckAssetAccessAsync("authorized-poster",source.Current.FieldId,"FIELD","WRITE",null)).ReturnsAsync(new AccessCheckResponse{HasAccess=true});
        var observed=new HashSet<string>(StringComparer.Ordinal);f.OnRead=table=>{if(table is "AR_INVOICE" or "GL_ACCOUNT" or "GL_ACCOUNT_MAPPING" or "COMPANY_LEDGER_PERIOD"){if(table!="AR_INVOICE")Assert.NotNull(((ITaskTransactionEvidence)f.Native.Source.Object).ActiveTransaction);if(((ITaskTransactionEvidence)f.Native.Source.Object).ActiveTransaction is not null)observed.Add(table);}};
        f.Native.FailCommit=true;var unknown=await Assert.ThrowsAsync<OilGasApiException>(()=>client.PostCompanySalesJournalAsync(command));Assert.Equal(HttpStatusCode.Conflict,unknown.StatusCode);Assert.Single(f.Native.Rows.OfType<SALES_JOURNAL_POSTING_INTENT>());Assert.Empty(f.Native.Rows.OfType<GL_ENTRY>());Assert.Empty(f.Native.Rows.OfType<SALES_JOURNAL_POSTING_OUTCOME>());f.OnRead=null;f.Native.FailCommit=false;
        var retained=await client.GetCompanySalesJournalPostingRecoveryAsync("statutory","KWD",preparation.JournalId);retained.Require();Assert.Null(retained.Outcome);Assert.Equal(JsonSerializer.Serialize(command),JsonSerializer.Serialize(retained.Intent!.Restore()));
        f.OnRead=table=>{if(table is "AR_INVOICE" or "GL_ACCOUNT" or "GL_ACCOUNT_MAPPING" or "COMPANY_LEDGER_PERIOD"){if(table!="AR_INVOICE")Assert.NotNull(((ITaskTransactionEvidence)f.Native.Source.Object).ActiveTransaction);if(((ITaskTransactionEvidence)f.Native.Source.Object).ActiveTransaction is not null)observed.Add(table);}};var result=await client.PostCompanySalesJournalAsync(command);result.Require(command);f.OnRead=null;var recovered=await client.GetCompanySalesJournalPostingRecoveryAsync("statutory","KWD",preparation.JournalId);recovered.Require();Assert.Equal(JsonSerializer.Serialize(result),JsonSerializer.Serialize(recovered.Outcome));Assert.Equal("POSTED",result.Journal.Header.STATUS);Assert.Equal(2,result.Entries.Count);Assert.Equal(5,f.Native.Writes);foreach(var table in new[]{"AR_INVOICE","GL_ACCOUNT","GL_ACCOUNT_MAPPING","COMPANY_LEDGER_PERIOD"})Assert.Contains(table,observed);
        host.Context.Permissions=grants.Where(value=>value!="Accounting.PostSalesJournal").ToArray();var readonlyRecovery=await client.GetCompanySalesJournalPostingRecoveryAsync("statutory","KWD",preparation.JournalId);Assert.NotNull(readonlyRecovery.Outcome);Assert.Equal(5,f.Native.Writes);
        host.Context.Actor="readonly-accountant";host.Context.Permissions=["Accounting.View","Accounting.ReviewPostedSalesLedger"];host.Client.DefaultRequestHeaders.Remove("X-Test-Actor");host.Client.DefaultRequestHeaders.Add("X-Test-Actor","readonly-accountant");using var readerCompany=CompanyGLAccountHttpTests.Selected(actor:"readonly-accountant",grants:host.Context.Permissions);var reader=CompanyGLAccountHttpTests.Client(host.Client,readerCompany);
        var ledger=await reader.GetCompanySalesPostedLedgerAsync(source.Current.ReceivableId,"statutory","KWD");ledger.Require(source.Current.Company,"readonly-accountant","statutory","KWD",source.Current.ReceivableId);Assert.Single(ledger.Journals);Assert.Equal("authorized-poster",ledger.Journals[0].PostedBy);Assert.Equal(2,ledger.Journals[0].Lines.Count);var publicJson=JsonSerializer.Serialize(ledger);Assert.DoesNotContain("COMMAND_JSON",publicJson);Assert.DoesNotContain("WORKFLOW_JSON",publicJson);Assert.DoesNotContain("OUTCOME_JSON",publicJson);
        host.Context.Permissions=["Accounting.View"];var readDenied=await Assert.ThrowsAsync<OilGasApiException>(()=>reader.GetCompanySalesPostedLedgerAsync(source.Current.ReceivableId,"statutory","KWD"));Assert.Equal(HttpStatusCode.Forbidden,readDenied.StatusCode);Assert.Equal(5,f.Native.Writes);

    }
}
#endif
